import asyncio
import core
nick_users={}
async def send(w,line):
    w.write((line+'\r\n').encode()); await w.drain()
async def handle(r,w):
    nick=None; user=None; token=None; registered=False
    try:
        while True:
            raw=await r.readline()
            if not raw: break
            line=raw.decode(errors='ignore').rstrip('\r\n')
            if not line: continue
            parts=line.split(' ',1); cmd=parts[0].upper(); arg=parts[1] if len(parts)>1 else ''
            if cmd=='PASS': token=arg.lstrip(':')
            elif cmd=='NICK':
                candidate=arg.split()[0] if arg else ''
                if candidate in nick_users and nick_users[candidate] is not w:
                    await send(w,f':huddle 433 * {candidate} :Nickname is already in use')
                    continue
                nick=candidate
            elif cmd=='USER':
                user=arg.split()[0] if arg else ''
            elif cmd=='PING':
                await send(w,':huddle PONG huddle '+arg)
            elif cmd=='QUIT':
                break
            elif cmd in ('PONG','NAMES','WHO','LIST','TOPIC','MODE'):
                continue
            elif cmd=='PRIVMSG':
                if not registered: continue
            else:
                await send(w,f':huddle 421 {nick or "*"} {cmd} :Unknown command')
            if not registered and nick and user:
                u=core.user_for_token(token)
                if not u:
                    await send(w,f':huddle 464 {nick} :Password incorrect'); break
                nick_users[nick]=w; registered=True
                for code,text in [('001','Welcome'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle'),('005','CASEMAPPING=rfc1459')]:
                    await send(w,f':huddle {code} {nick} :{text}')
                await send(w,f':huddle 422 {nick} :MOTD File is missing')
    finally:
        if nick and nick_users.get(nick) is w: del nick_users[nick]
        w.close()
        try: await w.wait_closed()
        except: pass
async def main():
    server=await asyncio.start_server(handle,'0.0.0.0',6667)
    async with server: await server.serve_forever()
if __name__=='__main__': asyncio.run(main())
